// The lease bearer vectors were generated by the server and checked against
// its verifier: a bearer is accepted for its service id and refused for any
// other id. The lease token implementation documents the byte format.
// Regenerate a row with mintLeaseBearer(t, []byte(row.secret), time.Unix(row.unixTs, 0), row.service).
//
// The last row is deliberately awkward: a one-character secret at second zero.
// A timestamp is canonical decimal — "0", never "+0" — and second zero is
// where an implementation that reached for padding would show it.
var leaseVectors = []struct {
	name    string
	secret  string
	unixTs  int64
	service string
	bearer  string
}{
	{
		name:    "an ordinary service at an ordinary second",
		secret:  "overlay wire vector secret",
		unixTs:  1756000000,
		service: "0198f3c1-6f2a-7b3c-9d4e-5f6a7b8c9d0e",
		bearer:  "bGVhc2U6MTc1NjAwMDAwMDowMTk4ZjNjMS02ZjJhLTdiM2MtOWQ0ZS01ZjZhN2I4YzlkMGU.q8dPpUZQJBaUUAq_aChLUsbuGI09uOGmrESbmK-P1Ho",
	},
	{
		name:    "the nil uuid, one second past the epoch",
		secret:  "overlay wire vector secret",
		unixTs:  1,
		service: "00000000-0000-0000-0000-000000000000",
		bearer:  "bGVhc2U6MTowMDAwMDAwMC0wMDAwLTAwMDAtMDAwMC0wMDAwMDAwMDAwMDA.GO6S4GrGZ5LtOnzdE9DEDmuz41DOsPB_aAOVLy9dXJA",
	},
	{
		name:    "a different secret entirely",
		secret:  "another secret entirely",
		unixTs:  2147483647,
		service: "ffffffff-ffff-ffff-ffff-ffffffffffff",
		bearer:  "bGVhc2U6MjE0NzQ4MzY0NzpmZmZmZmZmZi1mZmZmLWZmZmYtZmZmZi1mZmZmZmZmZmZmZmY.fvo07x0R5oti_3o261NNHYXPTcCOnd6FDeKBvpm3kT8",
	},
	{
		name:    "the awkward one: a one-byte secret at second zero",
		secret:  "x",
		unixTs:  0,
		service: "0198f3c1-6f2a-7b3c-9d4e-5f6a7b8c9d0e",
		bearer:  "bGVhc2U6MDowMTk4ZjNjMS02ZjJhLTdiM2MtOWQ0ZS01ZjZhN2I4YzlkMGU.uwUgEgvfgva18zXwut9R30u7D_-qmtpDFQwLJmTt_3M",
	},
}

const (
	// The service every test below leases, and its overlay address and port.
	leasedService = "0198f3c1-6f2a-7b3c-9d4e-5f6a7b8c9d0e"
	leasedOrg     = "acme"
	leasedAddress = "fd06:6e7:0:1::9"
	leasedPort    = 4444

	// This gateway's own address in that organization: what an onward dial has
	// to leave from.
	gatewaySource = "fd06:6e7:0:1::1"
)

func TestLeaseBearersMatchTheElixirVectors(t *testing.T) {
	for _, vector := range leaseVectors {
		t.Run(vector.name, func(t *testing.T) {
			at := time.Unix(vector.unixTs, 0)
			secrets := [][]byte{[]byte(vector.secret)}

			if err := VerifyLeaseBearer(secrets, vector.bearer, vector.service, at); err != nil {
				t.Fatalf("the app's own bearer was refused: %v", err)
			}

			// The id in the payload is the id the request must have named.
			if err := VerifyLeaseBearer(secrets, vector.bearer, "0198f3c1-0000-0000-0000-000000000000", at); err == nil {
				t.Error("a bearer minted for one service bought a lease to another")
			}

			if err := VerifyLeaseBearer([][]byte{[]byte("not the secret")}, vector.bearer, vector.service, at); err == nil {
				t.Error("a bearer verified under a secret that did not mint it")
			}
		})
	}
}

// Sixty seconds either side, and the same answer at both edges: two containers
// with two clocks, one of them a second fast, is not an attacker.
func TestLeaseBearerWindowIsSixtySecondsSymmetric(t *testing.T) {
	vector := leaseVectors[0]
	secrets := [][]byte{[]byte(vector.secret)}
	minted := time.Unix(vector.unixTs, 0)

	for _, drift := range []time.Duration{-60 * time.Second, -59 * time.Second, 0, 59 * time.Second, 60 * time.Second} {
		if err := VerifyLeaseBearer(secrets, vector.bearer, vector.service, minted.Add(drift)); err != nil {
			t.Errorf("a bearer %s from now was refused: %v", drift, err)
		}
	}

	for _, drift := range []time.Duration{-61 * time.Second, 61 * time.Second, time.Hour} {
		if err := VerifyLeaseBearer(secrets, vector.bearer, vector.service, minted.Add(drift)); err == nil {
			t.Errorf("a bearer %s from now was accepted", drift)
		}
	}
}

// A rotation is a window in which the two containers hold different current
// secrets, so a bearer minted under either has to keep verifying until it
// closes.
func TestLeaseBearerAcceptsAPreviousSecret(t *testing.T) {
	vector := leaseVectors[0]
	secrets := [][]byte{[]byte("the new secret"), []byte(vector.secret)}

	if err := VerifyLeaseBearer(secrets, vector.bearer, vector.service, time.Unix(vector.unixTs, 0)); err != nil {
		t.Fatalf("a bearer under the previous secret was refused: %v", err)
	}
}

// Three protocols ride one OVERLAY_INGRESS_SECRET, and none of the three is a
// message in either of the others. This is the crossing that would matter
// most: the bearer the gateway sends the app to fetch its own TLS private key,
// replayed at the door the app knocks on.
func TestLeaseRefusesTheCertBearer(t *testing.T) {
	cert, err := Bearer(testSecret, time.Now().Unix())
	if err != nil {
		t.Fatalf("minting the cert bearer: %v", err)
	}

	if err := VerifyLeaseBearer([][]byte{testSecret}, cert, leasedService, time.Now()); err == nil {
		t.Fatal("the cert bearer was accepted as a lease bearer")
	}
}

func TestLeaseBearerRefusesWhatIsNotABearerAtAll(t *testing.T) {
	vector := leaseVectors[0]
	secrets := [][]byte{[]byte(vector.secret)}
	at := time.Unix(vector.unixTs, 0)

	payload, mac, _ := strings.Cut(vector.bearer, ".")

	for _, token := range []string{
		"",
		"...",
		payload,                        // no MAC
		payload + "." + mac + "extra",  // a tampered MAC
		payload + "extra." + mac,       // a tampered payload
		"!" + payload + "." + mac,      // not base64
		strings.ToUpper(vector.bearer), // a different alphabet
	} {
		if err := VerifyLeaseBearer(secrets, token, vector.service, at); err == nil {
			t.Errorf("VerifyLeaseBearer accepted %q", token)
		}
	}
}

// mintLeaseBearer builds a bearer the way the app does, by its own path rather
// than by calling the code under test: what a MAC test is worth depends on the
// two sides being written separately.
func mintLeaseBearer(t *testing.T, secret []byte, at time.Time, nodeServiceID string) string {
	t.Helper()

	key, err := pbkdf2.Key(sha256.New, string(secret), []byte(leaseSalt), bearerIterations, bearerKeyLength)
	if err != nil {
		t.Fatalf("deriving the lease key: %v", err)
	}

	payload := "lease:" + strconv.FormatInt(at.Unix(), 10) + ":" + nodeServiceID
	mac := hmac.New(sha256.New, key)
	mac.Write([]byte(payload))

	return base64.RawURLEncoding.EncodeToString([]byte(payload)) +
		"." + base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
}

// dialled is one onward dial, as the lease made it.
type dialled struct {
	src netip.Addr
	dst netip.AddrPort
}

// dialRecorder stands in for `(*tsnode.Node).DialBound`, so what a lease does
// with a connection is provable without a head and a netstack.
type dialRecorder struct {
	calls chan dialled
	open  func() (net.Conn, error)
}

func newDialRecorder(open func() (net.Conn, error)) *dialRecorder {
	return &dialRecorder{calls: make(chan dialled, 8), open: open}
}

func (d *dialRecorder) dial(_ context.Context, src netip.Addr, dst netip.AddrPort) (net.Conn, error) {
	d.calls <- dialled{src: src, dst: dst}

	if d.open == nil {
		return nil, errors.New("this test has no upstream to open")
	}

	return d.open()
}

func (d *dialRecorder) waitForOne(t *testing.T) dialled {
	t.Helper()

	select {
	case call := <-d.calls:
		return call
	case <-time.After(2 * time.Second):
		t.Fatal("the lease never dialled the target")
		return dialled{}
	}
}

// stubDirectory is a Directory of one answer, so each status can be provoked
// without a rendered config document.
type stubDirectory struct {
	target Target
	err    error
}

func (s stubDirectory) Lookup(string) (Target, error) { return s.target, s.err }

// reachable is the ordinary directory: one approved service this gateway holds
// a grant in the organization of.
func reachable() stubDirectory {
	return stubDirectory{target: Target{
		Org:    leasedOrg,
		Source: netip.MustParseAddr(gatewaySource),
		Dest:   netip.AddrPortFrom(netip.MustParseAddr(leasedAddress), leasedPort),
	}}
}

// leaseLog is a log that can be read back, to prove what a refusal did not say.
type leaseLog struct {
	mu    sync.Mutex
	lines []string
}

func (l *leaseLog) logf(format string, args ...any) {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.lines = append(l.lines, fmt.Sprintf(format, args...))
}

func (l *leaseLog) String() string {
	l.mu.Lock()
	defer l.mu.Unlock()

	return strings.Join(l.lines, "\n")
}

// leaseAPI serves a Lease over loopback, which is where the docker network is
// in a test.
func leaseAPI(t *testing.T, lease *Lease) *httptest.Server {
	t.Helper()

	server := httptest.NewServer(lease)
	t.Cleanup(server.Close)

	return server
}

// askForLease posts the ordinary request: one field, and a bearer naming the
// same service.
func askForLease(t *testing.T, server *httptest.Server, nodeServiceID string) *http.Response {
	t.Helper()

	return askForLeaseWith(t, server,
		mintLeaseBearer(t, testSecret, time.Now(), nodeServiceID),
		fmt.Sprintf(`{"node_service_id":%q}`, nodeServiceID))
}

func askForLeaseWith(t *testing.T, server *httptest.Server, bearer, body string) *http.Response {
	t.Helper()

	request, err := http.NewRequest(http.MethodPost, server.URL+LeasePath, strings.NewReader(body))
	if err != nil {
		t.Fatalf("building the lease request: %v", err)
	}
	request.Header.Set("Content-Type", "application/json")
	if bearer != "" {
		request.Header.Set("Authorization", "Bearer "+bearer)
	}

	response, err := server.Client().Do(request)
	if err != nil {
		t.Fatalf("asking for a lease: %v", err)
	}
	t.Cleanup(func() { response.Body.Close() })

	return response
}

// granted reads the answer the app's own client reads.
func granted(t *testing.T, response *http.Response) leaseGranted {
	t.Helper()

	if response.StatusCode != http.StatusOK {
		t.Fatalf("the lease was refused with %d", response.StatusCode)
	}

	var answer leaseGranted
	if err := json.NewDecoder(response.Body).Decode(&answer); err != nil {
		t.Fatalf("reading the lease: %v", err)
	}

	return answer
}

func TestLeaseRequiresAValidBearer(t *testing.T) {
	lease := NewLease([][]byte{testSecret}, reachable(), newDialRecorder(nil).dial, nil)
	server := leaseAPI(t, lease)

	body := fmt.Sprintf(`{"node_service_id":%q}`, leasedService)

	for _, refusal := range []struct {
		name   string
		bearer string
	}{
		{name: "no bearer at all", bearer: ""},
		{name: "a bearer under another secret", bearer: mintLeaseBearer(t, []byte("another secret"), time.Now(), leasedService)},
		{name: "a bearer for another service", bearer: mintLeaseBearer(t, testSecret, time.Now(), "0198f3c1-0000-0000-0000-000000000000")},
		{name: "a bearer minted an hour ago", bearer: mintLeaseBearer(t, testSecret, time.Now().Add(-time.Hour), leasedService)},
		{name: "the cert bearer", bearer: certBearer(t)},
	} {
		t.Run(refusal.name, func(t *testing.T) {
			response := askForLeaseWith(t, server, refusal.bearer, body)

			if response.StatusCode != http.StatusUnauthorized {
				t.Fatalf("status %d, want %d", response.StatusCode, http.StatusUnauthorized)
			}
		})
	}
}

func certBearer(t *testing.T) string {
	t.Helper()

	bearer, err := Bearer(testSecret, time.Now().Unix())
	if err != nil {
		t.Fatalf("minting the cert bearer: %v", err)
	}

	return bearer
}

// The body names one service and nothing else. A body that named an address, a
// port or an organization would be a body a bearer-holder could steer, so a
// field this gateway does not know is a request it does not answer.
func TestLeaseRefusesABodyItDoesNotUnderstand(t *testing.T) {
	lease := NewLease([][]byte{testSecret}, reachable(), newDialRecorder(nil).dial, nil)
	server := leaseAPI(t, lease)

	bearer := mintLeaseBearer(t, testSecret, time.Now(), leasedService)

	for _, body := range []string{
		"",
		"not json",
		"{}",
		`{"node_service_id":""}`,
		fmt.Sprintf(`{"node_service_id":%q,"host":"172.18.0.9"}`, leasedService),
		fmt.Sprintf(`{"node_service_id":%q,"port":22}`, leasedService),
	} {
		response := askForLeaseWith(t, server, bearer, body)
		if response.StatusCode != http.StatusUnauthorized {
			t.Errorf("body %q was answered %d, want %d", body, response.StatusCode, http.StatusUnauthorized)
		}
	}
}

func TestLeaseAnswersEachDirectoryRefusalWithItsOwnStatus(t *testing.T) {
	for _, refusal := range []struct {
		err    error
		status int
	}{
		{err: ErrNoDocument, status: http.StatusServiceUnavailable},
		{err: ErrUnknownService, status: http.StatusNotFound},
		{err: ErrNotReachable, status: http.StatusForbidden},
		{err: errors.New("something nobody planned for"), status: http.StatusServiceUnavailable},
	} {
		t.Run(refusal.err.Error(), func(t *testing.T) {
			lease := NewLease([][]byte{testSecret}, stubDirectory{err: refusal.err}, newDialRecorder(nil).dial, nil)
			server := leaseAPI(t, lease)

			response := askForLease(t, server, leasedService)
			if response.StatusCode != refusal.status {
				t.Fatalf("status %d, want %d", response.StatusCode, refusal.status)
			}
		})
	}
}

// A gateway that is serving but holds no config document has no authority to
// say whether a service exists, and a retry is the right answer to that —
// which is not true of a 403 or a 404.
func TestLeaseRefusesBeforeTheFirstConfigDocument(t *testing.T) {
	lease := NewLease([][]byte{testSecret}, &Services{}, newDialRecorder(nil).dial, nil)
	server := leaseAPI(t, lease)

	response := askForLease(t, server, leasedService)
	if response.StatusCode != http.StatusServiceUnavailable {
		t.Fatalf("status %d, want %d", response.StatusCode, http.StatusServiceUnavailable)
	}
}

func TestLeaseReturnsHostPortAndTTL(t *testing.T) {
	lease := NewLease([][]byte{testSecret}, reachable(), newDialRecorder(nil).dial, nil)
	server := leaseAPI(t, lease)

	answer := granted(t, askForLease(t, server, leasedService))

	// The host is the address this request actually reached — by construction
	// one the caller can dial, because its own packet arrived there.
	local, err := netip.ParseAddrPort(server.Listener.Addr().String())
	if err != nil {
		t.Fatalf("reading the server's address: %v", err)
	}
	if answer.Host != local.Addr().String() {
		t.Errorf("the lease is on %q, want the address the request reached, %s", answer.Host, local.Addr())
	}
	if answer.Port == 0 || uint16(answer.Port) == local.Port() {
		t.Errorf("the lease is on port %d, which is not a port of its own", answer.Port)
	}
	if answer.ExpiresIn != int(leaseTTL/time.Second) {
		t.Errorf("expires_in = %d, want %d", answer.ExpiresIn, int(leaseTTL/time.Second))
	}

	// And it is really there.
	conn, err := net.DialTimeout("tcp", net.JoinHostPort(answer.Host, strconv.Itoa(answer.Port)), time.Second)
	if err != nil {
		t.Fatalf("the leased listener did not accept: %v", err)
	}
	conn.Close()
}

// This gateway holds a grant in every organization, so a dial
// that did not pin its source would leave from the primary address and be
// dropped by every other organization's packet filter.
func TestLeaseDialsTheTargetWithTheOrgsSourceAddressPinned(t *testing.T) {
	recorder := newDialRecorder(nil)
	lease := NewLease([][]byte{testSecret}, reachable(), recorder.dial, nil)
	server := leaseAPI(t, lease)

	answer := granted(t, askForLease(t, server, leasedService))
	conn, err := net.DialTimeout("tcp", net.JoinHostPort(answer.Host, strconv.Itoa(answer.Port)), time.Second)
	if err != nil {
		t.Fatalf("dialling the lease: %v", err)
	}
	defer conn.Close()

	call := recorder.waitForOne(t)
	if call.src != netip.MustParseAddr(gatewaySource) {
		t.Errorf("the dial left from %s, want this gateway's own address in %s, %s", call.src, leasedOrg, gatewaySource)
	}
	if want := netip.AddrPortFrom(netip.MustParseAddr(leasedAddress), leasedPort); call.dst != want {
		t.Errorf("the dial went to %s, want %s", call.dst, want)
	}
}

// One lease, one connection. The listener is gone the moment the requester's
// connection is taken, so a second connection has nothing to reach.
func TestLeaseListenerClosesOnFirstAccept(t *testing.T) {
	recorder := newDialRecorder(nil)
	lease := NewLease([][]byte{testSecret}, reachable(), recorder.dial, nil)
	server := leaseAPI(t, lease)

	answer := granted(t, askForLease(t, server, leasedService))
	address := net.JoinHostPort(answer.Host, strconv.Itoa(answer.Port))

	first, err := net.DialTimeout("tcp", address, time.Second)
	if err != nil {
		t.Fatalf("the first connection was refused: %v", err)
	}
	defer first.Close()

	// The dial is what says the connection was taken, so the listener is
	// closed by the time the second attempt is made — no sleeping at a race.
	recorder.waitForOne(t)

	if !refusesConnections(t, address) {
		t.Fatal("the leased listener took a second connection")
	}
}

// Ten seconds, used or not: a listener left for a caller that has stopped is a
// listener nobody is coming back for.
func TestLeaseListenerClosesOnTTLExpiry(t *testing.T) {
	lease := NewLease([][]byte{testSecret}, reachable(), newDialRecorder(nil).dial, nil)
	lease.TTL = 100 * time.Millisecond
	server := leaseAPI(t, lease)

	answer := granted(t, askForLease(t, server, leasedService))
	address := net.JoinHostPort(answer.Host, strconv.Itoa(answer.Port))

	if !refusesConnections(t, address) {
		t.Fatal("the leased listener was still there well past its TTL")
	}
}

// refusesConnections waits for an address to stop accepting, and says whether
// it did within a bound. Polled rather than slept at: what is being proved is
// that the listener goes, not how many milliseconds it takes.
func refusesConnections(t *testing.T, address string) bool {
	t.Helper()

	deadline := time.Now().Add(3 * time.Second)
	for time.Now().Before(deadline) {
		conn, err := net.DialTimeout("tcp", address, 200*time.Millisecond)
		if err != nil {
			return true
		}
		conn.Close()
		time.Sleep(10 * time.Millisecond)
	}

	return false
}

// The source binding is a boundary, not a race a stranger dialling first can
// win: a connection from anywhere else is closed and the lease goes on waiting
// for the one it was granted to.
func TestLeaseListenerRefusesAConnectionFromAnotherSource(t *testing.T) {
	recorder := newDialRecorder(nil)
	lease := NewLease([][]byte{testSecret}, reachable(), recorder.dial, nil)

	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("binding a lease listener: %v", err)
	}

	// The requester is an address nothing in this test dials from, so every
	// connection below is a stranger's.
	held := make(chan struct{})
	go func() {
		defer close(held)
		lease.hold(t.Context(), listener, netip.MustParseAddr("10.9.9.9"), reachable().target, time.Now().Add(5*time.Second))
	}()

	for attempt := range 2 {
		conn, err := net.DialTimeout("tcp", listener.Addr().String(), time.Second)
		if err != nil {
			t.Fatalf("attempt %d was not even accepted, so the lease stopped listening: %v", attempt, err)
		}

		// Closed with nothing said. A read that returns EOF at once is the
		// stranger being shown the door.
		conn.SetReadDeadline(time.Now().Add(time.Second))
		if _, err := conn.Read(make([]byte, 1)); !errors.Is(err, io.EOF) {
			t.Errorf("attempt %d was not closed: %v", attempt, err)
		}
		conn.Close()
	}

	select {
	case call := <-recorder.calls:
		t.Fatalf("a stranger's connection was dialled onward to %s", call.dst)
	default:
	}

	// Closing the listener is what ends it early; nothing else does, which is
	// the point of the paragraph on hold.
	listener.Close()
	<-held
}

// And the requester's own connection is taken and forwarded.
func TestLeaseForwardsTheRequestersConnection(t *testing.T) {
	upstream := echoServer(t)

	recorder := newDialRecorder(func() (net.Conn, error) {
		return net.DialTimeout("tcp", upstream, time.Second)
	})
	lease := NewLease([][]byte{testSecret}, reachable(), recorder.dial, nil)
	server := leaseAPI(t, lease)

	answer := granted(t, askForLease(t, server, leasedService))

	conn, err := net.DialTimeout("tcp", net.JoinHostPort(answer.Host, strconv.Itoa(answer.Port)), time.Second)
	if err != nil {
		t.Fatalf("dialling the lease: %v", err)
	}
	defer conn.Close()

	if _, err := conn.Write([]byte("hello over the overlay")); err != nil {
		t.Fatalf("writing through the lease: %v", err)
	}

	conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	read := make([]byte, len("hello over the overlay"))
	if _, err := io.ReadFull(conn, read); err != nil {
		t.Fatalf("reading back through the lease: %v", err)
	}
	if string(read) != "hello over the overlay" {
		t.Errorf("the lease carried %q", read)
	}
}

// echoServer is the far end of an overlay dial, standing in for a customer's
// listener.
func echoServer(t *testing.T) string {
	t.Helper()

	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("binding the echo server: %v", err)
	}
	t.Cleanup(func() { listener.Close() })

	go func() {
		for {
			conn, err := listener.Accept()
			if err != nil {
				return
			}
			go func() {
				defer conn.Close()
				_, _ = io.Copy(conn, conn)
			}()
		}
	}()

	return listener.Addr().String()
}

func TestTwoConcurrentLeasesGetDifferentPorts(t *testing.T) {
	lease := NewLease([][]byte{testSecret}, reachable(), newDialRecorder(nil).dial, nil)
	server := leaseAPI(t, lease)

	first := granted(t, askForLease(t, server, leasedService))
	second := granted(t, askForLease(t, server, leasedService))

	if first.Port == second.Port {
		t.Fatalf("two leases were handed the same port %d, so one caller's connection could be another's", first.Port)
	}
}

// An authenticated caller must not be able to make this process hold an
// unbounded number of sockets. Above the ceiling the answer is 429, which is
// the answer that means "ask again".
func TestLeaseBoundsHowManyAreOutstanding(t *testing.T) {
	lease := NewLease([][]byte{testSecret}, reachable(), newDialRecorder(nil).dial, nil)
	lease.slots = make(chan struct{}, 1)
	server := leaseAPI(t, lease)

	granted(t, askForLease(t, server, leasedService))

	response := askForLease(t, server, leasedService)
	if response.StatusCode != http.StatusTooManyRequests {
		t.Fatalf("the lease past the ceiling was answered %d, want %d", response.StatusCode, http.StatusTooManyRequests)
	}
}

// There is no renew and no release, and nothing else on this listener either:
// the app posts to one path and a gateway that answered another would be a
// gateway with a surface nobody wrote down.
func TestLeaseServesOnlyPostToTheLeasePath(t *testing.T) {
	lease := NewLease([][]byte{testSecret}, reachable(), newDialRecorder(nil).dial, nil)
	server := leaseAPI(t, lease)

	for _, unwanted := range []struct {
		method string
		path   string
		status int
	}{
		{method: http.MethodGet, path: LeasePath, status: http.StatusMethodNotAllowed},
		{method: http.MethodDelete, path: LeasePath, status: http.StatusMethodNotAllowed},
		{method: http.MethodPost, path: "/lease/renew", status: http.StatusNotFound},
		{method: http.MethodPost, path: "/lease/release", status: http.StatusNotFound},
		{method: http.MethodPost, path: "/", status: http.StatusNotFound},
	} {
		request, err := http.NewRequest(unwanted.method, server.URL+unwanted.path, nil)
		if err != nil {
			t.Fatalf("building %s %s: %v", unwanted.method, unwanted.path, err)
		}

		response, err := server.Client().Do(request)
		if err != nil {
			t.Fatalf("%s %s: %v", unwanted.method, unwanted.path, err)
		}
		response.Body.Close()

		if response.StatusCode != unwanted.status {
			t.Errorf("%s %s = %d, want %d", unwanted.method, unwanted.path, response.StatusCode, unwanted.status)
		}
	}
}

// A refusal is a status. Nothing it says, and nothing it writes down, is
// anything the caller sent — an error that echoed the request would be an
// error something could fill with the request's own Authorization header,
// which is how a secret reaches a log without anybody writing a line that logs
// one.
func TestLeaseRefusalsCarryNeitherTheBearerNorTheSecret(t *testing.T) {
	log := &leaseLog{}
	lease := NewLease([][]byte{testSecret}, stubDirectory{err: ErrNotReachable}, newDialRecorder(nil).dial, log.logf)
	server := leaseAPI(t, lease)

	bearer := mintLeaseBearer(t, testSecret, time.Now(), leasedService)
	response := askForLeaseWith(t, server, bearer, fmt.Sprintf(`{"node_service_id":%q}`, leasedService))

	answered, err := io.ReadAll(response.Body)
	if err != nil {
		t.Fatalf("reading the refusal: %v", err)
	}

	for name, sensitive := range map[string]string{"the bearer": bearer, "the secret": string(testSecret)} {
		if strings.Contains(string(answered), sensitive) {
			t.Errorf("the refusal's body carries %s", name)
		}
		if strings.Contains(log.String(), sensitive) {
			t.Errorf("the log carries %s:\n%s", name, log.String())
		}
	}
}

// The directory, against a document rather than a stub.
func documented(t *testing.T, leasable ...config.Service) *Services {
	t.Helper()

	grants, err := tsnode.ParseGrants([]tsnode.ConfigGrant{
		{Org: leasedOrg, Address: gatewaySource, Label: "gateway"},
	})
	if err != nil {
		t.Fatalf("parsing the grants: %v", err)
	}

	directory := &Services{}
	directory.Apply(&config.Document{Leasable: leasable}, grants)

	return directory
}

func approvedService() config.Service {
	return config.Service{
		ID:      leasedService,
		Kind:    "api",
		Org:     leasedOrg,
		Port:    leasedPort,
		State:   "approved",
		Address: leasedAddress,
	}
}

func TestServicesResolvesAnApprovedServiceToASourceAndADestination(t *testing.T) {
	target, err := documented(t, approvedService()).Lookup(leasedService)
	if err != nil {
		t.Fatalf("Lookup: %v", err)
	}

	if target.Source != netip.MustParseAddr(gatewaySource) {
		t.Errorf("the source is %s, want %s", target.Source, gatewaySource)
	}
	if want := netip.AddrPortFrom(netip.MustParseAddr(leasedAddress), leasedPort); target.Dest != want {
		t.Errorf("the destination is %s, want %s", target.Dest, want)
	}
	if target.Org != leasedOrg {
		t.Errorf("the organization is %q, want %q", target.Org, leasedOrg)
	}
}

func TestServicesRefusesBeforeTheFirstDocument(t *testing.T) {
	if _, err := (&Services{}).Lookup(leasedService); !errors.Is(err, ErrNoDocument) {
		t.Fatalf("Lookup before a document = %v, want %v", err, ErrNoDocument)
	}
}

func TestServicesRefusesAnIdTheDocumentDoesNotCarry(t *testing.T) {
	_, err := documented(t, approvedService()).Lookup("0198f3c1-0000-0000-0000-000000000000")
	if !errors.Is(err, ErrUnknownService) {
		t.Fatalf("Lookup of an unknown id = %v, want %v", err, ErrUnknownService)
	}
}

// Carried but not reachable, four ways. Each is a 403 and not a 404: the
// difference is a stale id on the app's side against a grant missing on the
// head's, and an operator is owed the distinction.
func TestServicesRefusesWhatItCannotReach(t *testing.T) {
	unapproved := approvedService()
	unapproved.State = "declared"

	addressless := approvedService()
	addressless.Address = ""

	portless := approvedService()
	portless.Port = 0

	// An organization this gateway holds no grant in: no source to dial from,
	// which is the cross-organization refusal at the moment it can still be
	// answered rather than eight seconds later in a packet filter.
	elsewhere := approvedService()
	elsewhere.Org = "another-org"
	elsewhere.Address = "fd06:6e7:0:2::9"

	for name, service := range map[string]config.Service{
		"not approved":         unapproved,
		"no address":           addressless,
		"no port":              portless,
		"another organization": elsewhere,
	} {
		t.Run(name, func(t *testing.T) {
			_, err := documented(t, service).Lookup(leasedService)
			if !errors.Is(err, ErrNotReachable) {
				t.Fatalf("Lookup = %v, want %v", err, ErrNotReachable)
			}
		})
	}
}

// The lease API over the real directory: cross-organization is a 403, and it
// is refused before a socket is bound rather than after a dial is dropped.
func TestLeaseRefusesAServiceInAnotherOrganization(t *testing.T) {
	elsewhere := approvedService()
	elsewhere.Org = "another-org"
	elsewhere.Address = "fd06:6e7:0:2::9"

	recorder := newDialRecorder(nil)
	lease := NewLease([][]byte{testSecret}, documented(t, elsewhere), recorder.dial, nil)
	server := leaseAPI(t, lease)

	response := askForLease(t, server, leasedService)
	if response.StatusCode != http.StatusForbidden {
		t.Fatalf("status %d, want %d", response.StatusCode, http.StatusForbidden)
	}

	select {
	case call := <-recorder.calls:
		t.Fatalf("a refused lease dialled %s anyway", call.dst)
	default:
	}
}

// The gateway's own listener is in `services` but not in `leasable`, so a
// lease request for it is a 404 rather than giving the gateway's own port to
// a caller. This is the test that would have caught d3969fd9e, where the
// gateway applied `services` and leased nothing else.
func TestServicesRefusesAServiceNotInLeasable(t *testing.T) {
	grants, err := tsnode.ParseGrants([]tsnode.ConfigGrant{
		{Org: leasedOrg, Address: gatewaySource, Label: "gateway"},
	})
	if err != nil {
		t.Fatalf("parsing the grants: %v", err)
	}

	directory := &Services{}
	directory.Apply(&config.Document{Services: []config.Service{approvedService()}}, grants)

	_, err = directory.Lookup(leasedService)
	if !errors.Is(err, ErrUnknownService) {
		t.Fatalf("Lookup of a service not in leasable = %v, want %v", err, ErrUnknownService)
	}
}
